const app=document.querySelector('#app'),p=new URLSearchParams(location.search),bv=p.get('v');let player;
const photos=()=>`<div class="photo-alternatives">${SHOTS.map((s,i)=>`<figure><button class="photo-tile" type="button" style="background-position:${s.position}" data-photo="${i}" aria-label="打开${s.time}原图"></button><figcaption class="photo-caption">${s.time}<br>${s.caption}</figcaption></figure>`).join('')}</div>`;
