if(p.get('view')==='register'){app.innerHTML=`<section class="registration"><p class="video-meta">摄影社动态 / 资料登记</p><h1>春季摄影社 · 机位借用与归档</h1><p>登记与机身时间按拍摄日填写，上传日期单列。共享相册的提取码沿用“实拍月日四位 + 机位字母”。</p><div class="register-table-wrap"><table class="register-table" data-read="camera"><thead><tr>${['场次','实拍日','机位','片型','上传日','保管人'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody><tr><td>运动会试拍</td><td>2025-03-20</td><td>A</td><td>测试，未采用</td><td>03-20</td><td>摄影社</td></tr><tr><td>运动会正片</td><td>${FACTS.sports}</td><td>${FACTS.camera}</td><td>照片相册</td><td>${FACTS.uploaded}</td><td>mj</td></tr><tr><td>社团补拍</td><td>2025-03-22</td><td>B</td><td>招新补镜</td><td>03-24</td><td>mj</td></tr></tbody></table></div><p class="video-notice">机身只记录按快门的时刻；两张照片之间没有连续记录。</p><p><a href="index.html?v=${FACTS.bv}">返回春季运动会相册</a></p></section>`;}else if(bv&&bv.toLowerCase()!==FACTS.bv.toLowerCase()){app.innerHTML=`<div class="video-notice">找不到视频号 ${esc(bv)}，请核对原帖中的完整BV号。</div>`;}else {app.innerHTML=`<div class="video-layout"><div><div class="video-heading"><div class="tags">生活 &gt; 校园日常</div><h1>春季运动会 / 摄影社机位B</h1><div class="video-meta">1,426播放　·　9弹幕　·　上传 ${FACTS.uploaded} 18:06　·　${FACTS.bv}</div></div><section data-player tabindex="0" aria-label="相册播放器，空格播放暂停，左右键移动三秒"><div class="player-shell"><video preload="none" playsinline muted poster="../assets/sports-poster.webp"><source src="../assets/spring-album.mp4" type="video/mp4"><track src="../assets/spring-album.vtt" kind="captions" srclang="zh" label="中文画面说明" default></video><div class="dm-layer" aria-hidden="true"></div><div class="frame-stamp"></div><span class="frame-label">QH 摄影社 / 相册剪辑</span><div class="player-poster"><button type="button" aria-label="播放相册">▶</button><small>点击播放 / 00:48</small></div></div><div class="player-controls"><button data-play type="button" aria-label="播放或暂停">▶</button><button data-back type="button" aria-label="后退三秒">‹</button><input type="range" data-progress min="0" max="48" value="0" step="0.1" aria-label="播放进度"><button data-forward type="button" aria-label="前进三秒">›</button><span class="time" data-time>00:00 / 00:48</span><select data-speed aria-label="播放倍速"><option value="1">1×</option><option value="0.5">0.5×</option><option value="1.5">1.5×</option><option value="2">2×</option></select><button class="mute" data-mute type="button">静音</button><label><input type="checkbox" data-danmaku checked>弹幕</label></div><p data-caption class="album-summary" aria-live="off"></p></section><div class="video-actions"><button data-like>♡ 23</button><span>◇ 收藏 8</span><span>↗ 分享</span></div><div class="video-description"><p>高一高二跑比赛，高三在旁边帮忙。阴天拍出来颜色就这样，我没调。四组照片剪在一起，配乐是后加的，没有现场录音。</p><p>原片袋：<a href="../pan/index.html?folder=sports">pan.qinghe.local / 摄影社 / 机位B</a><br>提取码还是社里的老格式，见<a href="index.html?view=register">机位登记</a>，别拿上传那天来填。</p><details><summary>逐图原件与画面说明（不播放也能看）</summary>${photos()}</details></div><section class="comments"><h2>评论 <small>5</small></h2>${comments.map(([name,pin,text,date,avatar])=>`<article class="comment"><img src="../assets/avatar-${avatar}.svg" alt="${name}的头像" loading="lazy"><div class="comment-body"><p class="comment-name">${name}${name==='mj'?'　UP':''}</p><p>${pin?`<span class="pinned">${pin}</span>`:''}${text}</p><time>${date}　　赞　回复</time></div></article>`).join('')}</section></div><aside class="video-sidebar"><div class="video-author"><img src="../assets/avatar-5.svg" alt="mj的头像"><div><strong>青禾摄影社</strong><small>上传者 mj · 机位B</small></div></div><button class="follow" data-follow>＋ 关注摄影社</button><div class="up-note"><h3>归档说明</h3>学校开放机房可访问此镜像。照片原始时间见画面下方，节目时间与上传时间分别登记。<p><a href="index.html?view=register">摄影社机位登记 →</a></p></div><div class="related"><div class="related-thumb"></div><div>器材借用与存储卡返还<small>摄影社动态 · 03-24</small></div></div></aside></div>`;}
const {store,bindReading}=await start('video');bindReading(app);if(app.querySelector('[data-player]'))player=mountPlayer(app.querySelector('[data-player]'),{onRead:()=>store.collect('album',{text:'摄影社相册剪辑：四组独立照片，原始时间14:29、14:32、14:36、14:42；侧门有两人搬灰箱，背对镜头；不是连续录像。',url:location.pathname+location.search})});
app.addEventListener('click',async e=>{const jump=e.target.closest('[data-seek]');if(jump){player.seek(Number(jump.dataset.seek));app.querySelector('[data-player]').focus();}const photo=e.target.closest('[data-photo]');if(photo){const shot=SHOTS[Number(photo.dataset.photo)],d=document.createElement('dialog');d.className='photo-original';d.innerHTML=`<button type="button">关闭 ×</button><div class="photo-tile" data-read="album" data-snapshot="${esc(shot.time+'；'+shot.caption+'；相册由独立照片组成，不是连续录像。')}" role="img" aria-label="${esc(shot.caption)}" style="background-position:${shot.position}"></div><p>${shot.time}　${esc(shot.caption)}</p>`;document.body.append(d);d.showModal();bindReading(d);d.querySelector('button').addEventListener('click',()=>d.close());d.addEventListener('close',()=>d.remove());}if(e.target.matches('[data-like]'))e.target.textContent='♥ 24';if(e.target.matches('[data-follow]'))e.target.textContent='已关注';});
